#define TREE_START		-220
#define GROUND_PAUSE 	180
#define DEF_TREE_SPEED	2




int16_t bub_floor_x = 0;

void reInitBubStix(){
    bubtreewalk = bk_bub_tree1;
	bubguywalk = scrn_saver_bubba_char_frames[0];
	bubtreewalktmr = bubguywalktmr = 0;
	bubtreeframe = bubguyframe = 0;

	walk_tree_x = TREE_START;
	walk_tree_sx = DEF_TREE_SPEED;
	walk_guy_x = -50;
	walk_guy_sx = 2;

    ground_move_pause=GROUND_PAUSE;

    restart_screen_svr=0;
}

#define NUM_FLOATING_LEAVES 	8

static gfxbob_t bigtree;

typedef struct {
	gfxbob_t leaves;
	int16_t  x, y;
	int8_t   frameTmr, frameId, wobblex, wobbley;	// frames and wind effect
	int8_t 	sx, sy, waveIndex, reserved;
} leaves_t;

static leaves_t floatLeaves[NUM_FLOATING_LEAVES];



void setup_background_bub(){
    static const uint8_t gradient_cols[] = {
        32, 32, 32, 33,
        33, 34, 34, 35,
        35, 36, 36, 37,
        37, 38, 38, 39,
        39, 39
    };


    bigtree_x = 200;
    frontbush_x = 0;
    screensaver1_floor_x = 0;

    bigtree.imgdat = bubtreeforeground;
    bigtree.atlas_height = 150;
    bigtree.atlas_stride = 32;
    bigtree.height = 150;
    bigtree.width = 32;
    bigtree.scale = 200;


	for(int i = 0; i < NUM_FLOATING_LEAVES; i++){
		floatLeaves[i].leaves.imgdat = bub_leaves_img;
		floatLeaves[i].leaves.atlas_height = 48;
		floatLeaves[i].leaves.atlas_stride = 32;
		floatLeaves[i].leaves.height = 24;
		floatLeaves[i].leaves.width = 32;
		floatLeaves[i].leaves.scale = 100;
		floatLeaves[i].frameId = 0;
		floatLeaves[i].frameTmr = star_rand(9);	// nine lcd vbls
		floatLeaves[i].wobblex = 0;		// init value to 0
		floatLeaves[i].wobbley = 0;
		floatLeaves[i].x = 20 + (star_rand(380));
		floatLeaves[i].y = 20 + (star_rand(220));
		floatLeaves[i].sx = 3 + (star_rand(4));
		floatLeaves[i].sy = 1 + (star_rand(2));
		floatLeaves[i].waveIndex = star_rand(20);
	}
	
	

    const int16_t height = 124;
    const int16_t band_count = (int16_t)(sizeof(gradient_cols) / sizeof(gradient_cols[0]));
    const int16_t band_h = (int16_t)(height / band_count);
    int16_t band;

    gfx_usebuffer(&backbitmap);
    gfx_cls();

    for(band = 0; band < band_count; ++band) {
        int16_t y0 = (int16_t)(band * band_h) + 36;
        int16_t y1 = (band == (band_count - 1)) ? height : (int16_t)(y0 + band_h);
        uint8_t col = gradient_cols[band];
        uint8_t prev_col = (band > 0) ? gradient_cols[band - 1] : col;

        gfx_setcolour(col);
        gfx_rectf(0, y0, SCREEN_W, (int16_t)(y1 - y0));

        if(band > 0 && prev_col != col) {
            if((y0 + 1) < y1) {
                gfx_setcolour(prev_col);
                gfx_rectf(0, (int16_t)(y0 + 3), SCREEN_W, 2);
            }
        }
    }

    
    // this draws to the back buffer
    gfx_bitmap_t *front_a = gfx_getdrawbuffer();
    gfx_usebuffer(front_a);
    gfx_setcolour(16);
    gfx_rectf(0, 144, 480, 100);
    gfx_draw1bit(0, 104, 480, 40, bub_background, 16, front_a->bitmap);

    reInitBubStix();
    
}

#define WALK_PAUSE	60
#define WALKING_TIME	620


// Sine table: 32 steps scaled to a range of -4 to 4 (fixed-point / integer friendly)
static const int8_t sineLUT[32] = {
    0,  1,  2,  3,  4,  3,  2,  1,
    0, -1, -2, -3, -4, -3, -2, -1,
    0,  1,  2,  3,  4,  3,  2,  1,
    0, -1, -2, -3, -4, -3, -2, -1
};

static int8_t wavesteptmr = 0;

void do_bubbastix_playdemo_screensaver(){
	char timedate[64];
	uint8_t th, tm, ts;
	API_GetTime(&th, &tm, &ts);
	sprintf(timedate, "%02u:%02u:%02u", th, tm, ts);
	


    if(restart_screen_svr == 3) {
        reInitBubStix();
    }

    ground_move_pause--;
	if(ground_move_pause==1) bubguywalk = scrn_saver_bubba_char_frames[8];
	if(ground_move_pause==-WALK_PAUSE) {
		bubguywalk = scrn_saver_bubba_char_frames[0];
	}

	if(ground_move_pause<0 && ground_move_pause>-WALKING_TIME && (bubguywalk != scrn_saver_bubba_char_frames[8])){
		screensaver1_floor_x -=2;
        bigtree_x -= 5;
        frontbush_x -=3;
		if(screensaver1_floor_x<-284) screensaver1_floor_x += 284;
        if(bigtree_x < -64) bigtree_x = 520;
        if(frontbush_x < -320) frontbush_x += 320;
	}

	if (bubguywalktmr++ > 3) {
		bubguywalktmr = 0;
		if (bubguyframe++ > 6)
			bubguyframe = 0;

		if(bubguywalk != scrn_saver_bubba_char_frames[8])
			bubguywalk = scrn_saver_bubba_char_frames[bubguyframe];
	}

	if (bubguywalk != scrn_saver_bubba_char_frames[8]) {
		if (bubtreewalktmr++ > 3) {
			bubtreewalktmr = 0;
			if (bubtreeframe++ > 2)
				bubtreeframe = 0;
			bubtreewalk = scrn_saver_buffer_tree_frames[bubtreeframe];
		}

		if (ground_move_pause > 0 || ground_move_pause < -WALKING_TIME) {
			walk_tree_x += walk_tree_sx;
			if (walk_tree_x > 480) restart_screen_svr = restart_screen_svr | 0x02;

			walk_guy_x += walk_guy_sx;
			if(walk_guy_x>1000)	restart_screen_svr = restart_screen_svr | 0x01;
		}
	}


    for(int bf = 0; bf < (284 * 3); bf += 284)
        gfx_blit(scr_bub_floor, bf + screensaver1_floor_x, 214, 284, 96);

        


    gfx_blit(bubtreewalk, walk_tree_x, 222, treewalkwidth[bubtreeframe], 32);
    gfx_blit(gfx_bub_treehead, walk_tree_x + 4, 110, 64, 112);
    
    if(bubguywalk == scrn_saver_bubba_char_frames[8]){
        gfx_blit(bk_bub_treehide, walk_tree_x + 16, 222, 40, 16);
        gfx_blit(gfx_bubgutwut, walk_guy_x, 187, 24, 69);
    } else {
        gfx_blit(bubguywalk, walk_guy_x, 187, guywidthwidth[bubguyframe], guywidthheight[bubguyframe]);
    }

    for(int bf = 0; bf < (320 * 3); bf += 320)
        gfx_blit(frontbush, frontbush_x + bf, 240, 320, 80);


    bigtree.drawx = bigtree_x;
    bigtree.drawy = 33;

	wavesteptmr++;
	if(wavesteptmr > 2) wavesteptmr = 0;


	for(int i = 0; i < NUM_FLOATING_LEAVES; i++){
		if(floatLeaves[i].frameTmr++ > 9){
			floatLeaves[i].frameTmr = 0;
			if(floatLeaves[i].frameId++ > 0)floatLeaves[i].frameId = 0;
			floatLeaves[i].leaves.index = floatLeaves[i].frameId;
		}
        
        //floatLeaves[i].frameTmr = 9;    // nine lcd vbls

        // Advance wave index to progress the wind sway
		if(wavesteptmr==0){
        	floatLeaves[i].waveIndex = (floatLeaves[i].waveIndex + 1) & 31;
			// Apply movement using wobble offsets
        	floatLeaves[i].x -= (floatLeaves[i].sx + floatLeaves[i].wobblex);
        	floatLeaves[i].y += (floatLeaves[i].sy + floatLeaves[i].wobbley);
		} else {
			// Apply movement using wobble offsets
        	floatLeaves[i].x -= (floatLeaves[i].sx);
        	floatLeaves[i].y += (floatLeaves[i].sy);

		}

        // Fetch sinusoidal offsets from table
        floatLeaves[i].wobblex = sineLUT[floatLeaves[i].waveIndex];
        // Offset Y index slightly so X and Y wobble out-of-phase for natural motion
        floatLeaves[i].wobbley = sineLUT[(floatLeaves[i].waveIndex + 8) & 31];


        if(floatLeaves[i].x < -64) floatLeaves[i].x = 500;
        if(floatLeaves[i].y > 320) floatLeaves[i].y = -16;

        floatLeaves[i].leaves.drawx = floatLeaves[i].x;
        floatLeaves[i].leaves.drawy = floatLeaves[i].y;

        gfx_drawbob(&floatLeaves[i].leaves);
    }

/*
	for(int i = 0; i < NUM_FLOATING_LEAVES; i++){
		// dropping leaves
		leaves[i].index = 0;
		//leaves.flags
		leaves[i].drawx = 100;
		leaves[i].drawy = 100;
		
	}
*/	

	//exte	rn const uint8_t bub_leaves_img[];
	//extern const uint8_t *bub_leaves_animframes[];

    gfx_drawbob(&bigtree);

    gfx_drawtext(8,100, timedate);

    
}


